func GateText(locale, key string) string {
	if _, ok := chatgateCopy[locale]; !ok {
		locale = "en-US"
	}
	if extras, ok := chatgateExtraCopy[locale]; ok {
		if value, ok := extras[key]; ok {
			return chatbug039Text(key, value, chatgateExtraCopy["en-US"][key])
		}
	}
	copy, ok := chatgateCopy[locale]
	if !ok {
		copy = chatgateCopy["en-US"]
	}
	return chatbug039Text(key, copy[key], chatgateCopy["en-US"][key])
}

